function rotLoop() {
   // Sin limite de tiempo para el giro automatico.
   if (autoStopped && !userDragging && Math.abs(delX) < 0.02) return;
   // Smooth out manual dragging changes
   var t = (dragX *= 0.98) - delX;
   delX += t / 10;

   var t = dragAmm + curDragX - newDel;
   newDel += t / 10;

   if (0 == def.phase.cur) {
      TweenMax.set(objects.c1, {
         rotationX: def.rot.start.x,
         rotationY: def.rot.start.y,
         rotationZ: def.rot.start.z,
      });
   } else if (1 == def.phase.cur) {
      // --- UPDATED LOGIC FOR AUTOMATIC RIGHT-TO-LEFT ROTATION ---
      // 1. Subtract a fixed value per frame to rotate right-to-left automatically (e.g., -0.5)
      // 2. Tras los 30s, conservar la inercia del ultimo arrastre hasta que se frene suavemente
      def.rot.cur.y += (autoStopped ? 0 : -0.5) + 0.1 * delX;

      // Keep values clean between 0 and 360 degrees if needed, or let GSAP handle continuous rotation
      def.rot.cur.x = def.rot.add.x;
      def.rot.cur.z = def.rot.add.z;

      // Shadow scaling math (kept from your original logic)
      var a = Math.abs(0.01 * delX);
      if (a > 40) a = 40;
      var s = 2.5 * (def.scale.x - a);
      if (s < 0) s = 0;
      var o = 0.4 * s;

      TweenMax.set(objects.shadow, { opacity: o, scaleX: s, scaleZ: s, scaleY: s });

      // Apply the updated continuous rotation tracking variable to the object
      TweenMax.set(objects.c1, {
         scaleX: 0.7,
         scaleY: 0.7,
         scaleZ: 0.7,
         rotationX: def.rot.cur.x,
         rotationY: def.rot.cur.y, // Continuous variable
         rotationZ: def.rot.cur.z,
         y: def.pos.y + nAdd.y,
      });
   }

   def.rot.start.active;
   lDragX = dragX;
   // No se actualiza constantemente después de 30s: solo durante un arrastre.
   if (!autoStopped || userDragging || Math.abs(delX) > 0.02) {
      scheduleRotationFrame();
   }
}
